from itertools import groupby
def cand(grid, row_mode='always', col_mode='always'):
    g=[list(r) for r in grid]; h=len(g); w=len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    dots=lambda v: v!=bg
    def has_run(vals):  # vals sorted list of indices; adjacent run?
        return any(b-a==1 for a,b in zip(vals,vals[1:]))
    def fill_line(get, setv, rng, mode):
        idx=[k for k in rng if dots(get(k))]
        if len(idx)<2: return
        if mode=='run' and not has_run(idx): return
        for a,b in zip(idx,idx[1:]):
            for k in range(a+1,b):
                if not dots(get(k)): setv(k,2)
    for i in range(h):
        fill_line(lambda j,i=i: g[i][j], lambda k,v,i=i: g[i].__setitem__(k,v), range(w), row_mode)
    for j in range(w):
        fill_line(lambda i,j=j: g[i][j], lambda k,v,j=j: g[k].__setitem__(j,v), range(h), col_mode)
    return g

